// 新签发与既有批准历史分开：失权使新签发不可用，但不回溯篡改已受领承诺的原来源。
#include "political_governance_agency_access.hpp"
#include "political_governance_agency_detail.hpp"
namespace hanmo::resident {namespace {
// DTO只投影原offer/真实接受，observed必须是当前或实际issue截面，不能传任意tick造许可。
PoliticalGovernanceAgencySource source(const PoliticalGovernanceAgencyContext& x,const PoliticalGovernanceAgencyOffer& o,const PoliticalGovernanceAgencyAnswer& a,Integer observed,Integer remaining){const auto& p=*x.catalog.policies.find(o.policy_id);return {x.common.state().identity,o.id,a.id,p.id,o.delegate_actor_id,{o.organization_id,o.office_id,o.office_epoch,o.issuer_actor_id},o.appointment_grant_id,o.commission_grant_id,p.jurisdiction_id,p.commission_policy_id,p.public_inventory_id,o.jurisdiction_revision,o.tick,a.tick,o.valid_through_tick,observed,remaining};}
}
Outcome<PoliticalGovernanceAgencySource> PoliticalGovernanceAgencyAccess::agency_for_commission(const StableId& offer,const StableId& actor)const{
 using namespace governance_agency_detail;const auto& x=context_;if(x.phase)return {false,{},common_failure("PoliticalGovernanceAgencyStableCommandRequired").error};const auto* o=x.state.offers.find(offer);if(!o||o->delegate_actor_id!=actor)return {false,{},common_failure("PoliticalGovernanceAgencyNotKnown",offer).error};auto v=validate_political_governance_agency_sources(x);if(!v.ok)return {false,{},v.error};const auto* a=answer(x.state,offer);if(!a||!a->accept||revoked(x.state,offer)||x.common.tick()>o->valid_through_tick)return {false,{},common_failure("PoliticalGovernanceAgencyInactive",offer).error};const auto& p=*x.catalog.policies.find(o->policy_id);const auto& j=*x.politics.jurisdictions.find(p.jurisdiction_id);Integer issued=0;for(const auto& row:x.state.issues.rows())if(row.second.offer_fact_id==offer)++issued;if(issued>=p.maximum_issues)return {false,{},common_failure("PoliticalGovernanceAgencyIssueLimit",offer).error};v=office_current(x,*o,political_governance_agency_offer_command);if(!v.ok)return {false,{},v.error};v=person_current(x,actor,o->organization_id,j.seat_place_id);if(!v.ok)return {false,{},v.error};v=x.seat(p,x.common.tick(),{});if(!v.ok)return {false,{},v.error};const auto* policy=x.governance_catalog.commission_policies.find(p.commission_policy_id);const auto* rule=policy?x.governance_catalog.appeasement_rules.find(policy->rule_id):nullptr;if(!rule)return {false,{},common_failure("InvalidGovernanceCommissionPolicy",p.commission_policy_id).error};auto authority=check_authority(x.common,x.organizations,x.organization_catalog,{o->organization_id,o->office_id,o->office_epoch,o->issuer_actor_id},"political_commission_governance",{ScopeRef::Kind::site,j.seat_place_id},rule->cash_amount);if(!authority.ok)return {false,{},authority.error};return {true,source(x,*o,*a,x.common.tick(),p.maximum_issues-issued),{}};
}
Outcome<PoliticalGovernanceAgencySource> PoliticalGovernanceAgencyAccess::agency_before_issue(const StableId& offer,const StableId& issue,Integer tick)const{
 const auto& x=context_;const auto* at=x.state.issues.find(issue);if(!at||at->id!=issue||at->offer_fact_id!=offer||at->tick!=tick||!political_governance_agency_fact_sequence(x.common,issue,"political_governance_agency_issued"))return {false,{},common_failure("PoliticalGovernanceAgencyIssueBoundaryRequired",issue).error};auto v=validate_political_governance_agency_sources(x);if(!v.ok)return {false,{},v.error};const auto* o=x.state.offers.find(offer);const auto* a=x.state.answers.find(at->acceptance_fact_id);if(!o||!a||!a->accept)return {false,{},common_failure("PoliticalGovernanceAgencyIssueMismatch",issue).error};Integer previous=0;for(const auto& row:x.common.state().facts.rows()){if(row.first==issue)break;if(const auto* old=x.state.issues.find(row.first);old&&old->offer_fact_id==offer)++previous;}const auto& p=*x.catalog.policies.find(o->policy_id);return {true,source(x,*o,*a,tick,p.maximum_issues-previous),{}};
}
// 新批准ID独占前缀并恰一对应本次实际代理签字，删整个代理账也不能退回旧批准解析。
Outcome<PoliticalGovernanceAgencySource> PoliticalGovernanceAgencyAccess::agency_for_issued_authority(const StableId& authority)const{const auto& x=context_;auto n=organization_instance_sequence(authority,"politics_governance_agency_authority");if(!n||*n>=x.common.state().next_instance_id)return {false,{},common_failure("PoliticalGovernanceAgencyApprovalRequired",authority).error};const PoliticalGovernanceAgencyIssue* issue=nullptr;for(const auto& row:x.state.issues.rows())if(row.second.authority_fact_id==authority){if(issue)return {false,{},common_failure("PoliticalGovernanceAgencyApprovalAmbiguous",authority).error};issue=&row.second;}if(!issue)return {false,{},common_failure("PoliticalGovernanceAgencyApprovalSourceMissing",authority).error};return agency_before_issue(issue->offer_fact_id,issue->id,issue->tick);}
}
